package com.emssystem.emsnotificationservice.notification.entity; import com.emssystem.emsnotificationservice.notification.enums.NotificationType; import jakarta.persistence.*; import java.time.Instant;
@Entity @Table(name="notifications",indexes=@Index(name="idx_notification_employee_created",columnList="employee_id,created_at")) public class Notification{@Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id;@Column(name="employee_id",nullable=false) private Long employeeId;@Enumerated(EnumType.STRING) @Column(nullable=false,length=40) private NotificationType type;@Column(nullable=false,length=200) private String title;@Column(nullable=false,length=4000) private String body;@Column(name="read_at") private Instant readAt;@Column(name="created_at",nullable=false,updatable=false) private Instant createdAt;protected Notification(){}public Notification(Long employeeId,NotificationType type,String title,String body,Instant createdAt){this.employeeId=employeeId;this.type=type;this.title=title;this.body=body;this.createdAt=createdAt;}public Long getId(){return id;}public Long getEmployeeId(){return employeeId;}public NotificationType getType(){return type;}public String getTitle(){return title;}public String getBody(){return body;}public Instant getReadAt(){return readAt;}public Instant getCreatedAt(){return createdAt;}}
